namespace sv_ed905a4d74be4b2aba87490bda1d45d6.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires <see cref="OnChange"/> so every subscribed component re-renders
/// when new data arrives — even components that didn't trigger the poll.
/// Scoped lifetime ensures each circuit (user) has independent state.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    /// <summary>
    /// Subscribers must wrap StateHasChanged in InvokeAsync because
    /// this event fires from a background timer thread.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches fresh data and notifies ALL subscribers.
    /// Called by whichever component owns the polling timer.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentWarehouseId = warehouseId;
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

