@* Interactive component embedded in the static MainLayout.
   Uses CascadingValueSource<WarehouseInfo> to push the selection
   across render-mode boundaries to all interactive subscribers. *@

@rendermode InteractiveServer

@using sv_ed905a4d74be4b2aba87490bda1d45d6.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@inject InventoryAlertService AlertService

<select class="form-select form-select-sm" style="width:200px"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.Available)
    {
        <option value="@wh.WarehouseId">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = WarehouseInfo.Available[0].WarehouseId;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? _selectedId;
        var warehouse = WarehouseInfo.Available
            .First(w => w.WarehouseId == _selectedId);

        // Push to all [CascadingParameter] subscribers across render modes
        await WarehouseSource.NotifyChangedAsync(warehouse);

        // Immediately refresh alerts for the new warehouse
        await AlertService.RefreshAsync(_selectedId);
    }
}

@* Displays the current low-stock alert count as a badge.
   Subscribes to InventoryAlertService.OnChange so it updates
   whenever ANY component triggers a refresh — not just itself. *@

@rendermode InteractiveServer

@using sv_ed905a4d74be4b2aba87490bda1d45d6.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because OnChange fires from a timer thread
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer

@using sv_ed905a4d74be4b2aba87490bda1d45d6.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-header d-flex justify-content-between align-items-center">
        <span>Inventory Alerts — @(_warehouse?.Name ?? "No warehouse selected")</span>
        <span class="badge @(_alertCss) fs-6">@AlertService.CurrentAlertCount</span>
    </div>
    <div class="card-body">
        @if (AlertService.CurrentAlertCount == 0)
        {
            <p class="text-success mb-0">All items are above minimum stock levels.</p>
        }
        else
        {
            <p class="text-danger mb-0">
                <strong>@AlertService.CurrentAlertCount</strong> item(s) below minimum stock level.
            </p>
        }
        <p class="text-muted mt-2 mb-0">
            <small>Auto-refreshes every 10 seconds. Last check: @_lastCheck.ToString("T")</small>
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? _warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;
    private DateTime _lastCheck = DateTime.Now;

    private string _alertCss =>
        AlertService.CurrentAlertCount > 0 ? "bg-danger" : "bg-success";

    protected override void OnInitialized()
    {
        // Subscribe so this component re-renders when another component
        // (or this one) calls RefreshAsync
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    /// <summary>
    /// When the cascaded warehouse changes (user picked a different site),
    /// restart polling against the new warehouse.
    /// </summary>
    protected override async Task OnParametersSetAsync()
    {
        if (_warehouse is not null &&
            _warehouse.WarehouseId != AlertService.CurrentWarehouseId)
        {
            await AlertService.RefreshAsync(_warehouse.WarehouseId);
            _lastCheck = DateTime.Now;
        }
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        // Initial fetch
        if (_warehouse is not null)
        {
            await AlertService.RefreshAsync(_warehouse.WarehouseId);
            _lastCheck = DateTime.Now;
        }

        // Background polling loop
        _ = Task.Run(async () =>
        {
            try
            {
                while (await _timer.WaitForNextTickAsync(_cts.Token))
                {
                    if (_warehouse is not null)
                    {
                        await AlertService.RefreshAsync(_warehouse.WarehouseId);
                        _lastCheck = DateTime.Now;
                    }
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on dispose
            }
        });
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

